-- ============ V3__message.sql ============
CREATE TABLE IF NOT EXISTS `notice` ( `id` BIGINT NOT NULL COMMENT '通知主键', `user_id` BIGINT NOT NULL COMMENT '接收用户 → user.id', `title` VARCHAR(128) NOT NULL COMMENT '标题', `content` VARCHAR(500) DEFAULT NULL COMMENT '内容', `type` TINYINT NOT NULL DEFAULT 1 COMMENT '类型：1 系统 / 2 互动 / 3 审核', `is_read` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否已读', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', PRIMARY KEY (`id`), KEY `notice_idx_user` (`user_id`) ) COMMENT = '站内信/通知表';

-- ============ V4__feature_im_points_blog.sql ============
DROP TABLE IF EXISTS `chat_conversation`;
CREATE TABLE `chat_conversation` ( `id` BIGINT NOT NULL COMMENT '会话主键', `type` TINYINT NOT NULL DEFAULT 1 COMMENT '类型：1 单聊 / 2 群聊', `title` VARCHAR(64) DEFAULT NULL COMMENT '群聊名称；单聊为空', `owner_id` BIGINT DEFAULT NULL COMMENT '群主 / 创建人 → user.id', `last_message` VARCHAR(512) DEFAULT NULL COMMENT '最近一条消息预览', `last_message_time` DATETIME DEFAULT NULL COMMENT '最近消息时间', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `chat_conversation_idx_owner` (`owner_id`), KEY `chat_conversation_idx_type` (`type`) ) COMMENT = '聊天会话表（单聊 / 群聊）';
DROP TABLE IF EXISTS `chat_conversation_member`;
CREATE TABLE `chat_conversation_member` ( `id` BIGINT NOT NULL COMMENT '主键', `conversation_id` BIGINT NOT NULL COMMENT '会话 ID → chat_conversation.id', `user_id` BIGINT NOT NULL COMMENT '成员 ID → user.id', `role` TINYINT NOT NULL DEFAULT 2 COMMENT '角色：1 群主 / 2 成员', `last_read_message_id` BIGINT DEFAULT NULL COMMENT '最后已读消息 ID', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `chat_conversation_member_uk_conv_user` (`conversation_id`, `user_id`), KEY `chat_conversation_member_idx_user` (`user_id`) ) COMMENT = '会话成员关系表';
DROP TABLE IF EXISTS `chat_message`;
CREATE TABLE `chat_message` ( `id` BIGINT NOT NULL COMMENT '消息主键', `conversation_id` BIGINT NOT NULL COMMENT '会话 ID → chat_conversation.id', `sender_id` BIGINT NOT NULL COMMENT '发送人 → user.id', `content` VARCHAR(2000) NOT NULL COMMENT '消息内容', `type` TINYINT NOT NULL DEFAULT 1 COMMENT '类型：1 文本 / 2 图片 / 3 系统', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '状态：0 已发送 / 1 已读', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发送时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `chat_message_idx_conv_time` (`conversation_id`, `create_time`) ) COMMENT = '聊天消息表';
DROP TABLE IF EXISTS `points_account`;
CREATE TABLE `points_account` ( `user_id` BIGINT NOT NULL COMMENT '用户 ID（主键）→ user.id', `balance` INT NOT NULL DEFAULT 0 COMMENT '当前积分余额', `total_earned` INT NOT NULL DEFAULT 0 COMMENT '累计获得', `total_spent` INT NOT NULL DEFAULT 0 COMMENT '累计消费', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`user_id`) ) COMMENT = '用户积分账户表';
DROP TABLE IF EXISTS `points_product`;
CREATE TABLE `points_product` ( `id` BIGINT NOT NULL COMMENT '商品主键', `name` VARCHAR(64) NOT NULL COMMENT '商品名称', `description` VARCHAR(255) DEFAULT NULL COMMENT '商品描述', `image_url` VARCHAR(255) DEFAULT NULL COMMENT '商品图片', `cost_points` INT NOT NULL DEFAULT 0 COMMENT '兑换所需积分', `stock` INT NOT NULL DEFAULT 0 COMMENT '库存', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：1 上架 / 2 下架', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `points_product_idx_status` (`status`) ) COMMENT = '积分商城商品表';
DROP TABLE IF EXISTS `points_order`;
CREATE TABLE `points_order` ( `id` BIGINT NOT NULL COMMENT '订单主键', `user_id` BIGINT NOT NULL COMMENT '兑换人 → user.id', `product_id` BIGINT NOT NULL COMMENT '商品 ID → points_product.id', `product_name` VARCHAR(64) DEFAULT NULL COMMENT '商品名称快照', `cost_points` INT NOT NULL DEFAULT 0 COMMENT '兑换消耗积分', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '状态：0 待兑换 / 1 已兑换 / 2 已取消', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `points_order_idx_user` (`user_id`), KEY `points_order_idx_product` (`product_id`) ) COMMENT = '积分兑换订单表';
DROP TABLE IF EXISTS `blog_post`;
CREATE TABLE `blog_post` ( `id` BIGINT NOT NULL COMMENT '文章主键', `author_id` BIGINT NOT NULL COMMENT '作者 → user.id', `title` VARCHAR(128) NOT NULL COMMENT '标题', `cover_url` VARCHAR(255) DEFAULT NULL COMMENT '封面', `summary` VARCHAR(255) DEFAULT NULL COMMENT '摘要', `content` TEXT NOT NULL COMMENT '正文', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 草稿 / 1 已发布 / 2 已下架', `like_count` INT NOT NULL DEFAULT 0 COMMENT '点赞数', `comment_count` INT NOT NULL DEFAULT 0 COMMENT '评论数', `view_count` INT NOT NULL DEFAULT 0 COMMENT '浏览数', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `blog_post_idx_author` (`author_id`), KEY `blog_post_idx_status` (`status`) ) COMMENT = '博客文章表';
DROP TABLE IF EXISTS `blog_comment`;
CREATE TABLE `blog_comment` ( `id` BIGINT NOT NULL COMMENT '评论主键', `post_id` BIGINT NOT NULL COMMENT '文章 ID → blog_post.id', `user_id` BIGINT NOT NULL COMMENT '评论人 → user.id', `content` VARCHAR(1000) NOT NULL COMMENT '评论内容', `like_count` INT NOT NULL DEFAULT 0 COMMENT '点赞数', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `blog_comment_idx_post` (`post_id`), KEY `blog_comment_idx_user` (`user_id`) ) COMMENT = '博客评论表';
DROP TABLE IF EXISTS `blog_like`;
CREATE TABLE `blog_like` ( `id` BIGINT NOT NULL COMMENT '主键', `post_id` BIGINT NOT NULL COMMENT '文章 ID → blog_post.id', `user_id` BIGINT NOT NULL COMMENT '点赞人 → user.id', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `blog_like_uk_post_user` (`post_id`, `user_id`), KEY `blog_like_idx_post` (`post_id`) ) COMMENT = '博客点赞表';
INSERT INTO `points_account` (`user_id`, `balance`, `total_earned`, `total_spent`) VALUES (1, 500, 500, 0) ON DUPLICATE KEY UPDATE `balance` = `balance`;
INSERT INTO `points_product` (`id`, `name`, `description`, `image_url`, `cost_points`, `stock`, `status`) VALUES (2001, '书币月卡', '赠送 300 书币，30 天有效', NULL, 200, 100, 1), (2002, '墨阅定制书签', '金属书签一套', NULL, 150, 50, 1), (2003, '作者月度推荐位', '作品首页推荐 7 天', NULL, 800, 10, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);
