-- ============ V5__comment_like.sql ============
DROP TABLE IF EXISTS `comment_like`;
CREATE TABLE `comment_like` ( `id` BIGINT NOT NULL COMMENT '主键', `comment_id` BIGINT NOT NULL COMMENT '评论 ID → comment.id', `user_id` BIGINT NOT NULL COMMENT '点赞人 → user.id', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `comment_like_uk_comment_user` (`comment_id`, `user_id`), KEY `comment_like_idx_comment` (`comment_id`) ) COMMENT = '评论点赞表';

-- ============ V6__announcement_and_reward_fix.sql ============
ALTER TABLE `reward_order` ADD COLUMN `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除';
DROP TABLE IF EXISTS `announcement`;
CREATE TABLE `announcement` ( `id` BIGINT NOT NULL COMMENT '公告主键', `title` VARCHAR(128) NOT NULL COMMENT '标题', `content` TEXT NOT NULL COMMENT '正文', `type` TINYINT NOT NULL DEFAULT 1 COMMENT '类型：1 站内公告 / 2 活动 / 3 系统维护', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '状态：0 草稿 / 1 已发布 / 2 已下线', `is_top` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否置顶：0 否 / 1 是', `publish_time` DATETIME DEFAULT NULL COMMENT '发布时间', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `announcement_idx_status` (`status`), KEY `announcement_idx_top_time` (`is_top`, `publish_time`) ) COMMENT = '运营公告表';

-- ============ V7__points_earning.sql ============
DROP TABLE IF EXISTS `points_check_in`;
CREATE TABLE `points_check_in` ( `id` BIGINT NOT NULL COMMENT '主键', `user_id` BIGINT NOT NULL COMMENT '用户 ID（主键之一）→ user.id', `check_in_date` DATE NOT NULL COMMENT '签到日期 YYYY-MM-DD', `points` INT NOT NULL DEFAULT 0 COMMENT '本次签到发放积分', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '签到时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `points_check_in_uk_user_date` (`user_id`, `check_in_date`) ) COMMENT = '每日签到记录表';
DROP TABLE IF EXISTS `points_flow`;
CREATE TABLE `points_flow` ( `id` BIGINT NOT NULL COMMENT '主键', `user_id` BIGINT NOT NULL COMMENT '用户 ID → user.id', `biz_type` TINYINT NOT NULL COMMENT '业务类型：1 签到 / 2 阅读时长 / 3 评论奖励 / 4 系统发放 / 5 兑换消费', `points` INT NOT NULL COMMENT '积分变动（正获得 / 负消费）', `remark` VARCHAR(255) DEFAULT NULL COMMENT '备注', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发生时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `points_flow_idx_user` (`user_id`) ) COMMENT = '积分流水表（只增台账）';

-- ============ V8__merch_mall.sql ============
DROP TABLE IF EXISTS `merch_product`;
CREATE TABLE `merch_product` ( `id` BIGINT NOT NULL COMMENT '商品主键', `name` VARCHAR(128) NOT NULL COMMENT '商品名称', `description` VARCHAR(500) DEFAULT NULL COMMENT '商品描述', `image_url` VARCHAR(255) DEFAULT NULL COMMENT '商品图片', `price` DECIMAL(10,2) NOT NULL DEFAULT 0.00 COMMENT '售价（元）', `stock` INT NOT NULL DEFAULT 0 COMMENT '库存', `sales` INT NOT NULL DEFAULT 0 COMMENT '累计销量', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：1 上架 / 2 下架', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `merch_product_idx_status` (`status`) ) COMMENT = '周边商品表';
DROP TABLE IF EXISTS `merch_cart`;
CREATE TABLE `merch_cart` ( `id` BIGINT NOT NULL COMMENT '主键', `user_id` BIGINT NOT NULL COMMENT '用户 ID → user.id', `product_id` BIGINT NOT NULL COMMENT '商品 ID → merch_product.id', `quantity` INT NOT NULL DEFAULT 1 COMMENT '数量', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `merch_cart_uk_user_product` (`user_id`, `product_id`), KEY `merch_cart_idx_user` (`user_id`) ) COMMENT = '周边购物车表';
DROP TABLE IF EXISTS `merch_order`;
CREATE TABLE `merch_order` ( `id` BIGINT NOT NULL COMMENT '订单主键', `order_no` VARCHAR(32) NOT NULL COMMENT '订单号（一次结算一个，整单共用）', `user_id` BIGINT NOT NULL COMMENT '下单人 → user.id', `product_id` BIGINT NOT NULL COMMENT '商品 ID → merch_product.id', `product_name` VARCHAR(128) DEFAULT NULL COMMENT '商品名称快照', `quantity` INT NOT NULL DEFAULT 1 COMMENT '购买数量', `total_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00 COMMENT '本行金额（元）= price * quantity', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '状态：0 待支付 / 1 已支付 / 2 已取消', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下单时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `merch_order_idx_order_no` (`order_no`), KEY `merch_order_idx_user` (`user_id`) ) COMMENT = '周边订单表（一行一商品）';

-- ============ V9__ai_assistant.sql ============
DROP TABLE IF EXISTS `ai_session`;
CREATE TABLE `ai_session` ( `id` BIGINT NOT NULL COMMENT '会话主键', `user_id` BIGINT NOT NULL COMMENT '用户 ID → user.id', `title` VARCHAR(128) DEFAULT NULL COMMENT '会话标题（默认取首条提问截断）', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `ai_session_idx_user` (`user_id`) ) COMMENT = 'AI 客服会话表';
DROP TABLE IF EXISTS `ai_message`;
CREATE TABLE `ai_message` ( `id` BIGINT NOT NULL COMMENT '消息主键', `session_id` BIGINT NOT NULL COMMENT '会话 ID → ai_session.id', `role` TINYINT NOT NULL DEFAULT 1 COMMENT '角色：1 用户 / 2 助手', `content` VARCHAR(2000) NOT NULL COMMENT '消息内容', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发送时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `ai_message_idx_session` (`session_id`) ) COMMENT = 'AI 客服消息表';

-- ============ V10__audit_remark.sql ============
ALTER TABLE audit_task ADD COLUMN remark VARCHAR(255) NULL COMMENT '审核意见（通过/驳回理由，可空）';
ALTER TABLE audit_task ADD COLUMN operator_id BIGINT NULL COMMENT '审核操作人用户 ID（网关注入，可空）';

-- ============ V11__book_finish_apply.sql ============
CREATE TABLE IF NOT EXISTS `book_finish_apply` ( `id` BIGINT NOT NULL COMMENT '申请主键（雪花 ID）', `book_id` BIGINT NOT NULL COMMENT '作品 ID → book.id', `author_id` BIGINT NOT NULL COMMENT '申请人（作者）ID → user.id', `reason` VARCHAR(500) DEFAULT NULL COMMENT '完结申请理由（可空）', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '审核状态：0 待审核 / 1 通过 / 2 驳回', `auditor_id` BIGINT DEFAULT NULL COMMENT '审核人（管理员）ID → user.id', `audit_remark` VARCHAR(255) DEFAULT NULL COMMENT '审核意见（通过 / 驳回理由，可空）', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `book_finish_apply_idx_book_status` (`book_id`, `status`), KEY `book_finish_apply_idx_status_create` (`status`, `create_time`) ) COMMENT = '作品完结申请表';

-- ============ V12__system_management.sql ============
CREATE TABLE IF NOT EXISTS `sys_dept` ( `id` BIGINT NOT NULL COMMENT '部门主键（雪花 ID）', `parent_id` BIGINT NOT NULL DEFAULT 0 COMMENT '父部门 ID，0 表示顶级', `dept_name` VARCHAR(50) NOT NULL COMMENT '部门名称', `order_num` INT NOT NULL DEFAULT 0 COMMENT '显示顺序', `leader` VARCHAR(20) DEFAULT NULL COMMENT '负责人', `phone` VARCHAR(11) DEFAULT NULL COMMENT '联系电话', `email` VARCHAR(64) DEFAULT NULL COMMENT '邮箱', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 禁用 / 1 正常', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `sys_dept_idx_parent` (`parent_id`) ) COMMENT = '系统部门表';
CREATE TABLE IF NOT EXISTS `sys_user` ( `id` BIGINT NOT NULL COMMENT '用户主键（雪花 ID）', `dept_id` BIGINT NOT NULL DEFAULT 0 COMMENT '部门 ID → sys_dept.id，0 未分配', `username` VARCHAR(30) NOT NULL COMMENT '登录账号', `nickname` VARCHAR(30) NOT NULL COMMENT '昵称', `password` VARCHAR(72) NOT NULL COMMENT 'BCrypt 密码哈希', `email` VARCHAR(64) DEFAULT NULL COMMENT '邮箱', `phone` VARCHAR(11) DEFAULT NULL COMMENT '手机号', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 禁用 / 1 正常', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `sys_user_uk_username` (`username`), KEY `sys_user_idx_dept` (`dept_id`), KEY `sys_user_idx_status` (`status`) ) COMMENT = '系统用户表（运营后台操作员）';
CREATE TABLE IF NOT EXISTS `sys_role` ( `id` BIGINT NOT NULL COMMENT '角色主键（雪花 ID）', `role_name` VARCHAR(30) NOT NULL COMMENT '角色名称', `role_key` VARCHAR(50) NOT NULL COMMENT '角色标识（权限校验用，如 admin）', `data_scope` TINYINT NOT NULL DEFAULT 1 COMMENT '数据权限：1 全部 / 2 自定义部门 / 3 仅本人', `dept_ids` VARCHAR(255) DEFAULT NULL COMMENT '自定义数据权限部门 ID，逗号分隔（data_scope=2）', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 禁用 / 1 正常', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `sys_role_uk_role_key` (`role_key`), KEY `sys_role_idx_status` (`status`) ) COMMENT = '系统角色表';
CREATE TABLE IF NOT EXISTS `sys_menu` ( `id` BIGINT NOT NULL COMMENT '菜单主键（雪花 ID）', `parent_id` BIGINT NOT NULL DEFAULT 0 COMMENT '父菜单 ID，0 表示顶级', `menu_name` VARCHAR(50) NOT NULL COMMENT '菜单名称', `menu_type` TINYINT NOT NULL DEFAULT 1 COMMENT '类型：0 目录 / 1 菜单 / 2 按钮', `path` VARCHAR(128) DEFAULT NULL COMMENT '路由地址', `component` VARCHAR(128) DEFAULT NULL COMMENT '前端组件路径', `perms` VARCHAR(128) DEFAULT NULL COMMENT '权限标识（按钮级，如 system:user:add）', `icon` VARCHAR(64) DEFAULT NULL COMMENT '图标', `order_num` INT NOT NULL DEFAULT 0 COMMENT '显示顺序', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 禁用 / 1 正常', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `sys_menu_idx_parent` (`parent_id`) ) COMMENT = '系统菜单表（目录/菜单/按钮）';
CREATE TABLE IF NOT EXISTS `sys_user_role` ( `user_id` BIGINT NOT NULL COMMENT '用户 ID → sys_user.id', `role_id` BIGINT NOT NULL COMMENT '角色 ID → sys_role.id', PRIMARY KEY (`user_id`, `role_id`), KEY `sys_user_role_idx_role` (`role_id`) ) COMMENT = '用户-角色关联表';
CREATE TABLE IF NOT EXISTS `sys_role_menu` ( `role_id` BIGINT NOT NULL COMMENT '角色 ID → sys_role.id', `menu_id` BIGINT NOT NULL COMMENT '菜单 ID → sys_menu.id', PRIMARY KEY (`role_id`, `menu_id`), KEY `sys_role_menu_idx_menu` (`menu_id`) ) COMMENT = '角色-菜单关联表';

-- ============ V13__content_safety_and_reach.sql ============
CREATE TABLE IF NOT EXISTS `sensitive_word` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `word` VARCHAR(64) NOT NULL COMMENT '敏感词', `level` TINYINT NOT NULL DEFAULT 1 COMMENT '等级：1 拦截 / 2 告警（转人工）', `category` VARCHAR(32) DEFAULT NULL COMMENT '分类：政治/广告/谩骂/涉黄…', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 停用 / 1 启用', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `sensitive_word_uk_word` (`word`), KEY `sensitive_word_idx_status_level` (`status`, `level`) ) COMMENT='敏感词库';
CREATE TABLE IF NOT EXISTS `report` ( `id` BIGINT NOT NULL COMMENT '举报主键（雪花 ID）', `reporter_id` BIGINT NOT NULL COMMENT '举报人 → user.id', `target_type` TINYINT NOT NULL COMMENT '对象：1 书籍 / 2 章节 / 3 评论 / 4 用户', `target_id` BIGINT NOT NULL COMMENT '对象主键', `reason_type` TINYINT NOT NULL DEFAULT 1 COMMENT '原因：1 违规内容 / 2 广告 / 3 侵权 / 4 其他', `reason` VARCHAR(500) DEFAULT NULL COMMENT '补充说明', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '状态：0 待处理 / 1 属实 / 2 驳回', `handler_id` BIGINT DEFAULT NULL COMMENT '处理人 → 管理员 ID', `handle_remark` VARCHAR(255) DEFAULT NULL COMMENT '处理意见', `handle_time` DATETIME DEFAULT NULL COMMENT '处理时间', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `report_idx_status` (`status`), KEY `report_idx_target` (`target_type`, `target_id`), KEY `report_idx_reporter` (`reporter_id`) ) COMMENT='举报表';
CREATE TABLE IF NOT EXISTS `message_template` ( `id` BIGINT NOT NULL, `code` VARCHAR(64) NOT NULL COMMENT '模板编码，如 AUDIT_PASS / REPORT_RESULT', `name` VARCHAR(64) NOT NULL COMMENT '模板名称', `title_tpl` VARCHAR(255) DEFAULT NULL COMMENT '标题模板，占位符 {param}', `content_tpl` VARCHAR(1000) NOT NULL COMMENT '内容模板', `channels` VARCHAR(64) NOT NULL DEFAULT '1' COMMENT '默认渠道，逗号分隔：1 站内信/2 邮件/3 短信/4 推送', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 停用 / 1 启用', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `message_template_uk_code` (`code`) ) COMMENT='消息模板表';
CREATE TABLE IF NOT EXISTS `message_channel_record` ( `id` BIGINT NOT NULL, `user_id` BIGINT NOT NULL COMMENT '接收用户 → user.id', `channel` TINYINT NOT NULL COMMENT '渠道：1 站内信/2 邮件/3 短信/4 推送', `template_code` VARCHAR(64) DEFAULT NULL COMMENT '模板编码', `target` VARCHAR(128) DEFAULT NULL COMMENT '投递地址（邮箱/手机号）', `title` VARCHAR(128) DEFAULT NULL, `content` VARCHAR(1000) DEFAULT NULL, `biz_type` VARCHAR(64) DEFAULT NULL COMMENT '业务类型，如 AUDIT / REPORT', `biz_id` BIGINT DEFAULT NULL COMMENT '业务主键', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '0 待发 / 1 成功 / 2 失败', `error_msg` VARCHAR(255) DEFAULT NULL, `retry_count` INT NOT NULL DEFAULT 0, `send_time` DATETIME DEFAULT NULL, `is_deleted` TINYINT(1) NOT NULL DEFAULT 0, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `message_channel_record_idx_user` (`user_id`), KEY `message_channel_record_idx_status` (`status`), KEY `message_channel_record_idx_template` (`template_code`) ) COMMENT='消息触达记录表';
