-- ============ V14__system_dict_config_log.sql ============
CREATE TABLE IF NOT EXISTS `sys_dict_type` ( `id` BIGINT NOT NULL COMMENT '字典类型主键（雪花 ID）', `dict_name` VARCHAR(50) NOT NULL COMMENT '字典名称，如 小说状态', `dict_type` VARCHAR(100) NOT NULL COMMENT '字典类型编码，如 novel_status', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 停用 / 1 启用', `remark` VARCHAR(255) DEFAULT NULL COMMENT '备注', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `sys_dict_type_uk_dict_type` (`dict_type`) ) COMMENT = '字典类型表';
CREATE TABLE IF NOT EXISTS `sys_dict_data` ( `id` BIGINT NOT NULL COMMENT '字典数据主键（雪花 ID）', `dict_type` VARCHAR(100) NOT NULL COMMENT '所属字典类型编码 → sys_dict_type.dict_type', `dict_label` VARCHAR(100) NOT NULL COMMENT '字典标签（展示用）', `dict_value` VARCHAR(100) NOT NULL COMMENT '字典键值（存储用）', `dict_sort` INT NOT NULL DEFAULT 0 COMMENT '显示顺序', `is_default` TINYINT NOT NULL DEFAULT 0 COMMENT '是否默认：0 否 / 1 是', `status` TINYINT NOT NULL DEFAULT 1 COMMENT '状态：0 停用 / 1 启用', `remark` VARCHAR(255) DEFAULT NULL COMMENT '备注', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `sys_dict_data_idx_dict_type` (`dict_type`) ) COMMENT = '字典数据表';
CREATE TABLE IF NOT EXISTS `sys_config` ( `id` BIGINT NOT NULL COMMENT '参数主键（雪花 ID）', `config_name` VARCHAR(100) NOT NULL COMMENT '参数名称，如 默认章节字数', `config_key` VARCHAR(100) NOT NULL COMMENT '参数键名，如 system.chapter.word-count', `config_value` VARCHAR(500) DEFAULT NULL COMMENT '参数键值', `is_system` TINYINT NOT NULL DEFAULT 0 COMMENT '是否内置参数：0 否 / 1 是（内置不可删除）', `remark` VARCHAR(255) DEFAULT NULL COMMENT '备注', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `sys_config_uk_config_key` (`config_key`) ) COMMENT = '系统参数配置表';
CREATE TABLE IF NOT EXISTS `sys_oper_log` ( `id` BIGINT NOT NULL COMMENT '日志主键（雪花 ID）', `module` VARCHAR(50) DEFAULT NULL COMMENT '业务模块，如 字典管理', `business_type` TINYINT NOT NULL DEFAULT 0 COMMENT '业务类型：0 其它 / 1 新增 / 2 修改 / 3 删除 / 4 导出 / 5 强退 / 6 生成代码', `request_method` VARCHAR(10) DEFAULT NULL COMMENT 'HTTP 请求方式：GET/POST/PUT/DELETE', `url` VARCHAR(255) DEFAULT NULL COMMENT '请求 URL', `operator_id` BIGINT DEFAULT NULL COMMENT '操作人员 ID → sys_user.id', `operator_name` VARCHAR(50) DEFAULT NULL COMMENT '操作人员名称', `ip` VARCHAR(64) DEFAULT NULL COMMENT '操作 IP', `param` TEXT DEFAULT NULL COMMENT '请求参数（截断 2000 字符）', `result` TEXT DEFAULT NULL COMMENT '返回结果（截断 2000 字符）', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '操作状态：0 成功 / 1 失败', `error_msg` TEXT DEFAULT NULL COMMENT '错误信息', `cost_ms` INT DEFAULT NULL COMMENT '耗时（毫秒）', `oper_time` DATETIME DEFAULT NULL COMMENT '操作时间', PRIMARY KEY (`id`), KEY `sys_oper_log_idx_operator` (`operator_id`), KEY `sys_oper_log_idx_module` (`module`), KEY `sys_oper_log_idx_oper_time` (`oper_time`) ) COMMENT = '操作日志表';
CREATE TABLE IF NOT EXISTS `sys_logininfor` ( `id` BIGINT NOT NULL COMMENT '日志主键（雪花 ID）', `username` VARCHAR(50) DEFAULT NULL COMMENT '登录账号', `ip` VARCHAR(64) DEFAULT NULL COMMENT '登录 IP', `user_agent` VARCHAR(255) DEFAULT NULL COMMENT '浏览器 UA', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '登录状态：0 成功 / 1 失败', `msg` VARCHAR(255) DEFAULT NULL COMMENT '提示信息，如 登录成功 / 账号或密码错误', `login_time` DATETIME DEFAULT NULL COMMENT '登录时间', PRIMARY KEY (`id`), KEY `sys_logininfor_idx_username` (`username`), KEY `sys_logininfor_idx_login_time` (`login_time`) ) COMMENT = '系统登录日志表';
