-- ============ V22__follow_and_dynamic.sql ============
CREATE TABLE IF NOT EXISTS `follow_relation` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `fan_id` BIGINT NOT NULL COMMENT '粉丝（关注发起方）ID → user.id', `author_id` BIGINT NOT NULL COMMENT '被关注作者 ID → user.id', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `follow_relation_uk_follow_pair` (`fan_id`, `author_id`), KEY `follow_relation_idx_follow_author` (`author_id`), KEY `follow_relation_idx_follow_fan` (`fan_id`), KEY `follow_relation_idx_follow_create` (`create_time`) ) COMMENT = '关注关系表';
CREATE TABLE IF NOT EXISTS `user_dynamic` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `actor_user_id` BIGINT DEFAULT NULL COMMENT '动作发起者（打赏者 / 作者本人）ID → user.id', `actor_name` VARCHAR(64) DEFAULT NULL COMMENT '反规范化快照：动作发起者昵称', `author_id` BIGINT NOT NULL COMMENT '动态归属作者（进粉丝流的人）→ user.id', `author_name` VARCHAR(64) DEFAULT NULL COMMENT '反规范化快照：作者昵称', `book_id` BIGINT DEFAULT NULL COMMENT '关联作品 ID → book.id', `book_title` VARCHAR(128) DEFAULT NULL COMMENT '反规范化快照：作品标题', `dynamic_type` TINYINT NOT NULL COMMENT '动态类型：1 发布新作 / 2 作品完结 / 3 打赏 / 4 关注(预留)', `summary` VARCHAR(255) DEFAULT NULL COMMENT '可选补充文案（后端不拼全文，前端按 type+字段渲染）', `ref_id` BIGINT DEFAULT NULL COMMENT '来源业务主键（bookId / rewardOrderId）', `ref_type` TINYINT NOT NULL COMMENT '来源类型：1=book发布 / 2=reward订单', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '排序键', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `user_dynamic_uk_dynamic_ref` (`ref_type`, `ref_id`), KEY `user_dynamic_idx_dynamic_actor` (`actor_user_id`), KEY `user_dynamic_idx_dynamic_author` (`author_id`), KEY `user_dynamic_idx_dynamic_create` (`create_time`) ) COMMENT = '用户动态表（关注流时间线 / 作者主页动态）';

-- ============ V23__member_subscription.sql ============
CREATE TABLE IF NOT EXISTS `member_tier` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `tier_code` VARCHAR(32) NOT NULL COMMENT '套餐编码（全局唯一，如 MONTHLY_BASIC）', `tier_name` VARCHAR(64) NOT NULL COMMENT '套餐名称', `monthly_price` DECIMAL(10,2) NOT NULL DEFAULT 0.00 COMMENT '包月价格（元）', `duration_days` INT NOT NULL DEFAULT 30 COMMENT '有效期天数', `ad_free` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '免广告权益：0 否 / 1 是', `discount_rate` DECIMAL(4,2) NOT NULL DEFAULT 1.00 COMMENT '折扣率（1.00 无折扣，0.90=9 折）', `badge` VARCHAR(64) DEFAULT NULL COMMENT '专属徽章名', `sort` INT NOT NULL DEFAULT 0 COMMENT '展示排序', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `member_tier_uk_member_tier_code` (`tier_code`), KEY `member_tier_idx_member_tier_sort` (`sort`) ) COMMENT = '会员套餐配置表';
CREATE TABLE IF NOT EXISTS `member_subscription` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `user_id` BIGINT NOT NULL COMMENT '订阅用户 ID → user.id', `tier_code` VARCHAR(32) NOT NULL COMMENT '套餐编码 → member_tier.tier_code', `tier_name` VARCHAR(64) DEFAULT NULL COMMENT '反规范化快照：套餐名称', `status` TINYINT NOT NULL DEFAULT 0 COMMENT '订阅状态：0 待支付 / 1 生效中 / 2 已过期 / 3 已取消', `start_time` DATETIME DEFAULT NULL COMMENT '生效开始时间', `end_time` DATETIME DEFAULT NULL COMMENT '生效结束时间（到期依据）', `order_no` VARCHAR(64) DEFAULT NULL COMMENT '订阅订单号', `pay_serial` VARCHAR(64) DEFAULT NULL COMMENT '支付渠道流水号', `channel` VARCHAR(32) DEFAULT NULL COMMENT '支付渠道标识', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), KEY `member_subscription_idx_member_sub_user` (`user_id`), KEY `member_subscription_idx_member_sub_status` (`status`), KEY `member_subscription_idx_member_sub_end` (`end_time`) ) COMMENT = '会员订阅记录表';

-- ============ V24__risk_behavior.sql ============
CREATE TABLE IF NOT EXISTS `risk_behavior_event` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `user_id` BIGINT NOT NULL COMMENT '行为用户 ID → user.id', `device_id` VARCHAR(64) DEFAULT NULL COMMENT '设备指纹 / 设备 ID', `event_type` VARCHAR(32) NOT NULL COMMENT '事件类型：LOGIN / SIGN_IN / REDEEM / REWARD / PUBLISH', `biz_id` BIGINT DEFAULT NULL COMMENT '关联业务主键', `ip` VARCHAR(64) DEFAULT NULL COMMENT '来源 IP', `risk_score` INT NOT NULL DEFAULT 0 COMMENT '风险分（预留）', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '采集时间', PRIMARY KEY (`id`), KEY `risk_behavior_event_idx_behavior_event_user` (`user_id`), KEY `risk_behavior_event_idx_behavior_event_device` (`device_id`), KEY `risk_behavior_event_idx_behavior_event_type` (`event_type`), KEY `risk_behavior_event_idx_behavior_event_create` (`create_time`) ) COMMENT = '用户行为事件表（风控采集源）';
CREATE TABLE IF NOT EXISTS `risk_rule` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `rule_code` VARCHAR(32) NOT NULL COMMENT '规则编码（全局唯一）', `rule_name` VARCHAR(64) NOT NULL COMMENT '规则名称', `rule_type` VARCHAR(32) NOT NULL COMMENT 'FREQ / DEVICE_MULTI_ACCOUNT / POINTS_ANOMALY / ACCOUNT_THEFT', `enabled` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '是否启用：0 关 / 1 开', `action` VARCHAR(16) NOT NULL COMMENT 'LIMIT / MARK / REVIEW / BLOCK', `config_json` VARCHAR(512) DEFAULT NULL COMMENT '规则参数 JSON（windowMinutes / threshold）', `is_deleted` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 否 / 1 是', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY (`id`), UNIQUE KEY `risk_rule_uk_risk_rule_code` (`rule_code`) ) COMMENT = '风控规则配置表';
CREATE TABLE IF NOT EXISTS `risk_decision` ( `id` BIGINT NOT NULL COMMENT '主键（雪花 ID）', `user_id` BIGINT DEFAULT NULL COMMENT '命中用户 ID', `device_id` VARCHAR(64) DEFAULT NULL COMMENT '命中设备 ID', `rule_code` VARCHAR(32) DEFAULT NULL COMMENT '命中规则编码', `event_type` VARCHAR(32) DEFAULT NULL COMMENT '触发事件类型', `decision` VARCHAR(16) NOT NULL COMMENT 'PASS / REVIEW / BLOCK', `risk_level` TINYINT NOT NULL DEFAULT 0 COMMENT '风险等级：0 无 / 1 低 / 2 中 / 3 高', `message` VARCHAR(255) DEFAULT NULL COMMENT '说明', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '决策时间', PRIMARY KEY (`id`), KEY `risk_decision_idx_decision_user` (`user_id`), KEY `risk_decision_idx_decision_create` (`create_time`), KEY `risk_decision_idx_decision_rule` (`rule_code`) ) COMMENT = '风控决策 / 处置记录表';
